import sys

def main():
    x, y = sys.stdin.read().split()
    m = len(y)
    dp = [0] * (m + 1)
    best = 0
    for ch in x:
        for j in range(m, 0, -1):
            if y[j - 1] == ch:
                v = dp[j - 1] + 1
                dp[j] = v
                if v > best:
                    best = v
    print(best)

